  const apps = Array.from(root.querySelectorAll('.hs-product')).map((el,index) => ({el,index,design:el.dataset.design,lang:['zh','en','tw'].includes(savedModel.language)?savedModel.language:'zh',stage:1,page:'workspace',direction:'traffic',selected:{type:'paper',id:'P01'},mode:el.dataset.design==='reading'?'list':'map',route:'A',answers:{},draftAnswers:{},draftReviews:{},draftNotes:{},draftScopeChecks:{},notes:{},noteOpen:false,scopeOpen:false,scopes:{},reviewOpen:false,reviewDecisions:{},history:[],notice:'',file:null,density:'comfortable',netMode:el.dataset.design==='reading'?'local':'overview',zoom:1,pan:{x:0,y:0},nodeOffsets:{},hoverNode:null}));
  function li(app){return app.lang==='en'?1:app.lang==='tw'?2:0;}
  function t(app,key){if(key==='project'&&app.previewProject)return esc(app.previewProject.topic);if(key==='structurePreview')return 'planned / unconnected';return words[key]?.[li(app)]??key;}
  function translated(app,arr){return arr[li(app)];}
  function esc(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function dirLabel(app,id){return translated(app,directionDefs.find(d=>d.id===id)?.labels || words.unknown);}
  function methodLabel(app,id){return translated(app,methodDefs.find(d=>d.id===id)?.labels || words.unknown);}
  function paperStatus(app,p){return t(app,{full:'readfull',abstract:'readabstract',unread:'notread',unknown:'unknownstatus'}[p.read]);}
  function scopeText(app){return t(app,app.stage===1?'scopeStage1':app.route==='B'?'scopeB':app.route==='C'?'scopeC':'scopebody');}
  function scopeKey(app){return app.stage===1?'stage1':'stage2-'+app.route;}
  function interactionKey(app){return scopeKey(app)+'-v1';}
  function selectionKey(app){return app.selected.type+':'+app.selected.id;}
  function reviewDecision(app){return app.reviewDecisions[interactionKey(app)]||'changes';}
