  function literature(app){return `<section class="hs-panel"><div class="hs-panel-head"><div><h2>${t(app,'literaturemap')}</h2><p>${t(app,'maphint')}</p></div><div class="hs-mode-switch"><button type="button" class="cursor-interaction" data-mode="map" aria-pressed="${app.mode==='map'}">${t(app,'map')}</button><button type="button" class="cursor-interaction" data-mode="list" aria-pressed="${app.mode==='list'}">${t(app,'list')}</button></div></div>${app.mode==='map'?graph(app):paperList(app,true)}</section>`;}
