    const nodes=radial?papers.map(p=>({key:'p-'+p.id,type:'paper',id:p.id,label:p.id,sub:p.short,full:p.title,unknown:!p.dirs.length})):networkNodes(app);
    const categoryMark=p=>p.dirs.length>1?'conic-gradient('+p.dirs.map((d,i)=>palette[d]+' '+i/p.dirs.length*100+'% '+(i+1)/p.dirs.length*100+'%').join(',')+')':palette[p.dirs[0]||'unknown'];
