  function coverage(app){const unknown=papers.filter(p=>!p.dirs.length),selected=app.direction==='unknown'?unknown:papers.filter(p=>p.dirs.includes(app.direction)),colors={traffic:'#dae8f4',coord:'#d7e9e8',transfer:'#f1dedb',evaluation:'#e4e9ed'};return `<section class="hs-panel"><div class="hs-panel-head"><div><h2>${t(app,'counttitle')}</h2><p>${t(app,'coveragehint')}</p></div><span class="hs-status">${papers.length} ${t(app,'unique')}</span></div><div class="hs-topic-atlas"><div class="hs-bubble-figure"><div class="hs-bubble-row">${directionDefs.map(d=>{const rows=papers.filter(p=>p.dirs.includes(d.id));return `<button type="button" class="hs-bubble-item cursor-interaction" data-direction="${d.id}" aria-pressed="${app.direction===d.id}" aria-label="${dirLabel(app,d.id)}: ${rows.length} ${t(app,'papers')}" style="--bubble-size:${34*Math.sqrt(rows.length)}px;--bubble-fill:${colors[d.id]}"><span class="hs-bubble">${rows.length}</span><span>${dirLabel(app,d.id)}<br>${t(app,'papers')}</span></button>`;}).join('')}</div><div class="hs-bubble-key"><span class="hs-bubble-unit"></span>${t(app,'areakey')}</div>${unknown.length?`<div class="hs-action-row"><button type="button" class="hs-button cursor-interaction" data-direction="unknown">${t(app,'unknown')} · ${unknown.length}</button></div>`:''}</div><aside class="hs-topic-papers"><h3>${dirLabel(app,app.direction)}</h3><p>${selected.length} ${t(app,'papers')} · ${t(app,'selected')}</p>${selected.map(p=>shownPaper(app,p)).join('')}</aside></div><div class="hs-footnote"><span>${t(app,'classified')} ${papers.length-unknown.length} · Unknown ${unknown.length}</span><span>${t(app,'notpercent')}</span></div></section>`;}
  function topicSelectionDetail(app){const panel=app.el.querySelector('.hs-topic-papers');if(!panel||app.selected.type!=='paper')return;const paper= papers.find(p=>p.id===app.selected.id&&(app.direction==='unknown'?!p.dirs.length:p.dirs.includes(app.direction)));if(!paper)return;const detail=document.createElement('div');detail.className='hs-topic-paper-detail';detail.setAttribute('aria-live','polite');detail.innerHTML=`<h3>${esc(paper.short)} · ${paper.year}</h3><p>${esc(translated(app,paper.summary))}</p><a href="${esc(paper.url)}" target="_blank" rel="noopener noreferrer">${t(app,'original')} ↗<br>${esc(paper.url)}</a><a href="${esc(paper.pdf)}" target="_blank" rel="noopener noreferrer">PDF ↗<br>${esc(paper.pdf)}</a>`;panel.appendChild(detail);}
  function stage1(app){if(!app.previewProject.hasResults)return `${topicPrep(app)}${heading(app)}${stageControls(app)}${resultOpen(app)}${emptyResult(app)}</div></details>${stageFeedback(app)}`;return `${topicPrep(app)}${heading(app)}${stageControls(app)}${resultOpen(app)}<section class="hs-panel"><div class="hs-panel-head"><div><h2>${t(app,'literaturemap')}</h2><p>${t(app,'nodehint')}</p></div><span class="hs-status">${t(app,'sample')}</span></div><div class="hs-atlas-grid"><section class="hs-panel">${app.design==='reading'?paperList(app,true):graph(app)}</section>${selectedDetail(app)}</div><p class="hs-labelnote">${t(app,'tagdemo')}</p></section>${app.design==='reading'?`<section class="hs-panel">${graph(app)}</section>`:''}${coverage(app)}</div></details>${stageFeedback(app)}${stageProcess(app)}${bottomAssistant(app)}`;}
  function flowSelection(app){return app.s2selected||{type:'route',id:app.route};}
  function flowGraph(app){
    const s=flowSelection(app),laneColors={A:palette.coord,B:palette.transfer,C:palette.evaluation};
    return `<div class="hs-route-lanes" role="group" aria-label="${t(app,'flowhint')}">${comparisonDefs.map(c=>{
      const g=gapDefs.find(g=>g.id===c.gap),r=routes.find(r=>r.id===g.route);
      const pressed=(type,id)=>s.type===type&&s.id===id;
      return `<section class="hs-lane" style="--lane-color:${laneColors[r.id]}"><div class="hs-lane-header"><button type="button" class="hs-lane-label cursor-interaction" data-route="${r.id}" aria-pressed="${app.route===r.id}">ROUTE ${r.id} · ${translated(app,r.title)}</button><small>${t(app,'pending')} · ${c.works.length} ${t(app,'papers')}</small></div><div class="hs-lane-sequence"><div class="hs-lane-cell"><small>${t(app,'evidence')}</small><div class="hs-paper-bundle">${c.works.map(id=>{const p=papers.find(p=>p.id===id);return `<button type="button" class="hs-paper-chip cursor-interaction" data-paper="${p.id}" aria-pressed="${pressed('paper',p.id)}" aria-label="${esc(p.title)} · ROUTE ${r.id}"><small>${p.id}</small>${esc(p.short)}</button>`;}).join('')}</div></div><span class="hs-lane-connector" aria-hidden="true">→</span><button type="button" class="hs-lane-cell cursor-interaction" data-comparison="${c.id}" aria-pressed="${pressed('comparison',c.id)}"><small>${t(app,'compare')}</small><strong>${translated(app,c.labels)}</strong></button><span class="hs-lane-connector" aria-hidden="true">→</span><button type="button" class="hs-lane-cell cursor-interaction" data-gap="${g.id}" aria-pressed="${pressed('gap',g.id)}"><small>${t(app,'pendingQuestion')}</small><strong>${translated(app,g.labels)}</strong></button><span class="hs-lane-connector" aria-hidden="true">→</span><button type="button" class="hs-lane-cell cursor-interaction" data-route="${r.id}" aria-pressed="${pressed('route',r.id)}"><small>${t(app,'routes')}</small><strong>${translated(app,r.title)}</strong></button></div></section>`;
    }).join('')}</div>`;
  }
  function flowDetail(app){const s=flowSelection(app);if(s.type==='paper')return selectedDetail(app);let title,body,works,routeIds;if(s.type==='comparison'){const c=comparisonDefs.find(c=>c.id===s.id);title=translated(app,c.labels);body=translated(app,c.body);works=c.works;routeIds=[gapDefs.find(g=>g.id===c.gap).route];}else if(s.type==='gap'){const g=gapDefs.find(g=>g.id===s.id);title=translated(app,g.labels);body=translated(app,g.body);works=comparisonDefs.find(c=>c.gap===g.id).works;routeIds=[g.route];}else{const r=routes.find(r=>r.id===s.id);title=translated(app,r.title);body=translated(app,r.question);works=comparisonDefs.filter(c=>gapDefs.find(g=>g.id===c.gap).route===s.id).flatMap(c=>c.works);routeIds=[s.id];}const route=routes.find(r=>r.id===routeIds[0]);return `<section class="hs-panel"><div class="hs-flow-detail" aria-live="polite"><div class="hs-detail-kicker">${t(app,'selected')} · ${esc(s.id)} · ${t(app,'sample')}</div><h2 class="hs-detail-title">${title}</h2><p class="hs-detail-text">${body}</p>${s.type==='route'?`<div class="hs-route-compact">${[['data','data'],['cost','cost'],['risk','risk']].map(([key,prop])=>`<div><strong>${t(app,key)}</strong>${translated(app,route[prop])}</div>`).join('')}</div>`:''}<div class="hs-detail-section"><h3>${t(app,'evidence')}</h3>${works.map(id=>papers.find(p=>p.id===id)).filter(Boolean).map(p=>shownPaper(app,p)).join('')}</div><div class="hs-action-row">${routeIds.map(id=>`<button type="button" class="hs-button cursor-interaction" data-route="${id}">ROUTE ${id}</button>`).join('')}${s.type==='route'?`<button type="button" class="hs-button hs-button-primary cursor-interaction" data-action="choose">${t(app,'chooseroute')}</button>`:''}</div><p class="hs-secondary-note">${t(app,'gaphint')}</p></div></section>`;}
  function stage2(app){return `${heading(app)}${taskRibbon(app)}${tracePanel(app)}<section class="hs-panel"><div class="hs-panel-head"><div><h2>${t(app,'flowtitle')}</h2><p>${t(app,'flowhint')}</p></div><span class="hs-status">${t(app,'pending')}</span></div>${flowGraph(app)}${flowDetail(app)}<p class="hs-labelnote">${t(app,'gaphint')}</p></section>${assistant(app)}`;}
  function drawFlow(app){/* Route lanes use three local sequence arrows, without cross-lane edges. */}
