  function taskRibbon(app){
    const tasks=taskDefs[app.stage],index=app.taskSteps?.[app.stage]??1,task=tasks[index],attempt=app.attemptViews?.[app.stage]||'v1';
    return `<section class="hs-task-panel"><div class="hs-task-top"><div><strong>${t(app,'stageTasks')}</strong><br><small>${t(app,'stagePreview')}</small></div><select data-attempt-view aria-label="${t(app,'viewAttempt')}"><option value="v1" ${attempt==='v1'?'selected':''}>${t(app,'currentDraft')}</option><option value="v0" ${attempt==='v0'?'selected':''}>${t(app,'historicDraft')}</option></select></div><div class="hs-task-strip" role="group" aria-label="${t(app,'stageTasks')}">${tasks.map((item,i)=>`<button type="button" class="hs-task-step cursor-interaction" data-task-step="${i}" aria-pressed="${index===i}"><span>${i+1}</span><span>${translated(app,item.label)}</span></button>`).join('')}</div><details class="hs-task-drawer" ${app.taskDrawerOpen?'open':''}><summary class="cursor-interaction">${t(app,'taskDetail')} · ${translated(app,task.label)}</summary><div class="hs-task-fields">${[['taskInput','input'],['taskOutput','output'],['taskWait','wait'],['taskNext','next']].map(([key,prop])=>`<div><strong>${t(app,key)}</strong>${translated(app,task[prop])}</div>`).join('')}</div><small>${attempt==='v0'?translated(app,['历史示例只影响此任务说明；下方交互仍属于当前 v1。','This history sample changes this task description only; actions below still belong to current v1.','歷史示例只影響此任務說明；下方互動仍屬目前 v1。'])+' ':''}${t(app,'viewOnly')}</small></details><div class="hs-loop-caption">${attempt==='v0'?translated(app,['历史示例仅用于查看；下方回答、笔记和研究范围仍属于当前 v1。','This history sample is view only; answers, notes and scope below still belong to current v1.','歷史示例僅供檢視；下方回答、筆記及研究範圍仍屬目前 v1。'])+'<br>':''}${t(app,app.stage===1?'loop1':'loop2')}</div></section>`;
  }
  function paperPeek(app){
    if(app.selected.type!=='paper')return '';
    const p=papers.find(p=>p.id===app.selected.id);if(!p)return '';
    return `<div class="hs-paper-peek" aria-live="polite"><strong>${esc(p.id+' · '+p.title)}</strong><p>${esc(translated(app,p.summary))}</p><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${t(app,'original')} ↗</a><a href="${esc(p.pdf)}" target="_blank" rel="noopener noreferrer">${t(app,'pdf')} ↗</a></div>`;
  }
  function similarityLabel(app,p,center){const value=similarityFor(center,p);return p.id===center.id?t(app,'selected'):value?Math.round(value.score*100)+'%':t(app,'unknownsim');}
  function drawSimilarityOverlay(app){
    const canvas=app.el.querySelector('.hs-network-canvas'),center=papers.find(p=>p.id===app.focal)||papers[0];if(!canvas)return;
    const centerNode=canvas.querySelector(`[data-paper="${center.id}"]`);if(!centerNode)return;
    const bounds=canvas.getBoundingClientRect(),point=node=>({x:+node.style.left.replace('px',''),y:+node.style.top.replace('px','')}),origin=point(centerNode),svg=canvas.querySelector('svg');
    svg.querySelectorAll('.hs-sim-edge').forEach(edge=>edge.remove());
    const edges=[];
    canvas.querySelectorAll('[data-node-type="paper"]').forEach(node=>{
      const p=papers.find(p=>p.id===node.dataset.paper),value=similarityFor(center,p),q=point(node);
      node.dataset.similarity=p.id===center.id?'center':value?String(value.score):'unknown';node.dataset.reference=center.id;node.dataset.center=String(p.id===center.id);
      node.querySelector('.hs-net-label').innerHTML=esc(p.id)+`<small>${esc(p.short)}</small><small>${similarityLabel(app,p,center)}</small>`;
      if(p.id!==center.id&&value&&value.score>0)edges.push(`<line class="hs-sim-edge" data-reference="${center.id}" data-work="${p.id}" data-score="${value.score}" x1="${origin.x}" y1="${origin.y}" x2="${q.x}" y2="${q.y}"></line>`);
    });
    svg.insertAdjacentHTML('beforeend',edges.join(''));canvas.dataset.layout='network-with-similarity';
  }
  function drawSimilarityRadial(app){
    const canvas=app.el.querySelector('.hs-network-canvas');if(!canvas||!canvas.clientWidth)return;
    const width=canvas.clientWidth,narrow=width<440,desired=narrow?Math.max(480,Math.ceil(papers.length/2)*92+40)+'px':'';
    if(canvas.style.height!==desired)canvas.style.height=desired;
    const height=canvas.clientHeight,cx=width/2,cy=height*.48,R=Math.min(width*.41,height*.37),inner=68,center=papers.find(p=>p.id===app.focal)||papers[0],rows=papers.filter(p=>p.id!==center.id),points={[center.id]:{x:cx,y:cy,center:true}};
    if(narrow){[center,...rows].forEach((p,i)=>{const value=p.id===center.id?null:similarityFor(center,p);points[p.id]={x:width*(i%2===0?.25:.75),y:45+Math.floor(i/2)*92,center:p.id===center.id,score:value?.score,unknown:p.id!==center.id&&!value};});}
    else rows.forEach((p,i)=>{const value=similarityFor(center,p);if(!value){points[p.id]={x:width*(i+1)/(rows.length+1),y:height-40,unknown:true};return;}const r=inner+(R-inner)*(1-value.score),angle=(-90+i*360/rows.length)*Math.PI/180;points[p.id]={x:cx+Math.cos(angle)*r,y:cy+Math.sin(angle)*r,score:value.score,r};});
    const camera=p=>({x:(p.x-cx)*app.zoom+cx+app.pan.x*width,y:(p.y-cy)*app.zoom+cy+app.pan.y*height}),origin=camera(points[center.id]);
    canvas.dataset.layout=narrow?'score-list':'center-relative-radial';
    const caption=app.el.querySelector('.hs-similarity-caption');if(caption)caption.textContent=center.id+' · '+center.short+' — '+t(app,narrow?'listMeaning':'radialMeaning');
    canvas.querySelectorAll('.hs-network-node').forEach(node=>{const p=papers.find(p=>p.id===node.dataset.paper),point=points[p.id],q=camera(point);node.style.left=q.x+'px';node.style.top=q.y+'px';node.dataset.similarity=point.score!==undefined?String(point.score):point.unknown?'unknown':'center';node.dataset.reference=center.id;node.dataset.radius=point.r!==undefined?String(point.r*app.zoom):'';node.querySelector('.hs-net-label').innerHTML=esc(p.id)+`<small>${esc(p.short)}</small><small>${similarityLabel(app,p,center)}</small>`;});
    const svg=canvas.querySelector('svg');svg.setAttribute('viewBox',`0 0 ${width} ${height}`);
    svg.innerHTML=narrow?'':rows.map(p=>{const point=points[p.id],q=camera(point);return point.score===undefined?'':`<line class="hs-sim-edge" data-reference="${center.id}" data-work="${p.id}" data-score="${point.score}" x1="${origin.x}" y1="${origin.y}" x2="${q.x}" y2="${q.y}"></line>`;}).join('')+explicitRelations.map(r=>{const a=points[r.from],b=points[r.to];if(!a||!b)return '';const x=camera(a),y=camera(b);return `<path class="hs-net-edge" data-strength="strong" data-explicit="true" style="--edge-color:#36658c" d="M ${x.x} ${x.y} L ${y.x} ${y.y}"></path>`;}).join('');
  }

