  function wbValidSnapshot(value){if(!value||typeof value!=='object'||!/^c[1-9]\d{0,8}$/.test(value.revision))return null;const topics=value.topics,ids=value.papers;if(!Array.isArray(topics)||topics.length<2||topics.length>3||!Array.isArray(ids)||ids.length<2||ids.length>6)return null;if(new Set(topics).size!==topics.length||new Set(ids).size!==ids.length)return null;if(!topics.every(id=>typeof id==='string'&&directionDefs.some(d=>d.id===id))||!ids.every(id=>typeof id==='string'&&papers.some(p=>p.id===id)))return null;return {revision:value.revision,topics:[...topics],papers:[...ids]};}
