  function localText(app,key){return translated(app,localWords[key]);}
  function topicPrep(app){return `<section class="lp-topic hs-panel" aria-label="${localText(app,'topicTitle')}"><div class="lp-topic-title"><div><span class="lp-eyebrow">PROJECT / TOPIC</span><h2>${localText(app,'topicTitle')}</h2></div><span class="hs-status">${localText(app,'preview')}</span></div><p>${localText(app,'topicHint')}</p><div class="lp-topic-fields"><label>${localText(app,'saved')}<select data-local-project>${app.previewProjects.map(p=>`<option value="${esc(p.id)}" ${p.id===app.previewProject.id?'selected':''}>${esc(p.label||p.topic)}</option>`).join('')}</select></label><label>${localText(app,'topic')}<div class="lp-topic-entry"><input data-local-topic value="${esc(app.previewDraftTopic)}" maxlength="240"><button type="button" class="hs-button hs-button-primary" data-local-create>${localText(app,'create')}</button></div></label></div><small>${localText(app,'draftNote')}</small></section>`;}
  function stageControls(app){return `${app.stage===2?`<div class="lp-handoff"><div><small>STAGE 1 → STAGE 2 · ${localText(app,'input2')}</small><strong>${localText(app,'inherited')}</strong><span>${app.previewProject.hasResults?localText(app,'s2Source'):localText(app,'notGenerated')}</span></div><button type="button" class="hs-button" data-local-source>${localText(app,'openStage1')} ↑</button></div>`:''}<details class="lp-operations hs-panel" data-local-operations="${app.stage}" ${app.previewOps[app.stage]?'open':''}><summary><div><strong>Stage${app.stage} · ${localText(app,'operations')}</strong><small>${localText(app,app.stage===1?'s1Steps':'s2Steps')}</small></div><span>${localText(app,'expand')} <b aria-hidden="true">⌄</b></span></summary><div class="lp-ops-body">${app.stage===1?`<label class="lp-scope-label">${localText(app,'scopeDraft')}<textarea data-local-scope rows="2" placeholder="${localText(app,'s1Scope')}">${esc(app.previewScopeDraft||'')}</textarea></label><button type="button" class="hs-button" data-local-save-scope>${localText(app,'saveScope')}</button>`:`<p class="lp-compare-input">${localText(app,'compareInput')}</p>`}<button class="hs-button hs-button-primary" type="button" disabled title="${localText(app,'cannotRun')}">${localText(app,app.stage===1?'start1':'start2')}</button><small class="lp-runtime-note">${localText(app,'cannotRun')}</small>${app.previewScopeSaved&&app.stage===1?`<p class="lp-draft-saved" role="status">${localText(app,'scopeSaved')}</p>`:''}</div></details>`;}
  function resultOpen(app){return `<details class="lp-results" data-local-results="${app.stage}" ${app.previewResultsOpen[app.stage]!==false?'open':''}><summary><strong>Stage${app.stage} · ${localText(app,app.stage===1?'result1':'result2')}</strong><span>${app.previewProject.hasResults?localText(app,'example'):localText(app,'notGenerated')} <b aria-hidden="true">⌄</b></span></summary><div class="lp-result-body">`;}
  function stageProcess(app){return `<details class="hs-panel lp-process" data-local-process="${app.stage}" ${app.previewProcessOpen[app.stage]?'open':''}><summary>Stage${app.stage} · ${localText(app,'process')}</summary><div class="lp-process-body">${taskRibbon(app)}${tracePanel(app)}</div></details>`;}
  function emptyResult(app){return `<section class="hs-panel lp-empty" data-local-empty="${app.stage}"><div class="lp-empty-icon" aria-hidden="true">${app.stage===1?'◎':'▤'}</div><span class="lp-eyebrow">STAGE ${String(app.stage).padStart(2,'0')} / OUTPUT</span><h2>${localText(app,'emptyTitle')}</h2><p>${localText(app,app.stage===1?'emptyBody':'emptyStage2')}</p><span class="hs-status">${localText(app,'notGenerated')}</span></section>`;}
  function bottomAssistant(app){return `<details class="hs-panel lp-assistant"><summary>${localText(app,'foldedAssistant')}<small>${localText(app,'cannotRun')}</small></summary><div>${assistant(app)}</div></details>`;}
  function localStage(app,stage,{historyMode='push'}={}){
    const previousStage=app.stage;
    app.previewStageContexts[app.stage]={selected:app.selected,topicPaperOpen:app.topicPaperOpen,focal:app.focal};app.stage=stage;app.page='workspace';Object.assign(app,app.previewStageContexts[stage]||{selected:{type:'paper',id:'P01'},topicPaperOpen:false,focal:'P01'});app.notice='';app.taskDrawerOpen=false;app.noteOpen=false;app.scopeOpen=false;app.reviewOpen=false;
    if(historyMode==='push' && typeof rt!=='undefined' && typeof v93Language==='function' && /^[A-Za-z0-9_-]{1,64}$/.test(rt.ref||'') && Number.isInteger(stage) && stage>=1 && stage<=6){
      const separator=location.hash.indexOf('?'),params=new URLSearchParams(separator<0?'':location.hash.slice(separator+1));
      params.set('stage',String(stage));params.set('lang',v93Language(app));
      const route=location.pathname+location.search+'#'+encodeURIComponent(rt.ref)+'?';
      if(!location.hash && Number.isInteger(previousStage) && previousStage>=1 && previousStage<=6){
        const previousParams=new URLSearchParams(params);previousParams.set('stage',String(previousStage));
        history.replaceState(history.state,'',route+previousParams.toString());
      }
      const target=route+params.toString();
      if(target!==location.pathname+location.search+location.hash)history.pushState(history.state,'',target);
    }
  }
  const localContextKeys=['selected','direction','focal','route','answers','draftAnswers','draftReviews','draftNotes','draftScopeChecks','notes','scopes','reviewDecisions','history','compareTopics','comparePapers','evidenceRecords','productView','reviewNeedsRecheck','collection','compareTag','relationFocus','topicPaperOpen','s2selected','taskSteps','attemptViews','previewOps','previewStageContexts','previewResultsOpen','previewProcessOpen','previewScopeDraft','previewScopeSaved','previewFeedback'];
  function localSnapshot(app){return JSON.parse(JSON.stringify(Object.fromEntries(localContextKeys.map(key=>[key,app[key]]).filter(([,v])=>v!==undefined))));}
  function localSwitch(app,project){app.previewContexts[app.previewProject.id]=localSnapshot(app);const state=app.previewContexts[project.id];if(state)Object.assign(app,JSON.parse(JSON.stringify(state)));else{Object.assign(app,{answers:{},draftAnswers:{},draftReviews:{},draftNotes:{},draftScopeChecks:{},notes:{},scopes:{},reviewDecisions:{},history:[],previewOps:{1:false,2:false},previewStageContexts:{},previewResultsOpen:{1:true,2:true},previewProcessOpen:{1:false,2:false},previewScopeDraft:'',previewScopeSaved:false,previewFeedback:{}});}app.previewProject=project;app.traceOpen=false;app.taskDrawerOpen=false;app.noteOpen=false;app.scopeOpen=false;app.reviewOpen=false;app.notice='';render(app);}
  apps.forEach(app=>{
    app.previewProjects=[{id:'v6-sample',topic:'强化学习用于交通信号控制',hasResults:true},{id:'empty',topic:'新研究项目',hasResults:false}];
    app.previewProject=app.previewProjects[0];app.previewDraftTopic='强化学习用于自动驾驶决策';app.previewOps={1:false,2:false};app.previewContexts={};app.previewStageContexts={};app.previewResultsOpen={1:true,2:true};app.previewProcessOpen={1:false,2:false};app.previewScopeDraft='';app.previewScopeSaved=false;
    app.el.addEventListener('click',event=>{if(!event.target.closest('[data-local-save-scope]'))return;event.stopImmediatePropagation();app.previewScopeDraft=app.el.querySelector('[data-local-scope]').value;app.previewScopeSaved=true;render(app);},true);
    app.el.addEventListener('click',event=>{if(!event.target.closest('[data-local-source]'))return;event.stopImmediatePropagation();localStage(app,1);render(app);app.el.querySelector('.hs-atlas-grid, [data-local-empty]')?.scrollIntoView({behavior:'smooth',block:'start'});},true);
    app.el.addEventListener('click',event=>{const button=event.target.closest('[data-local-create]');if(!button)return;event.stopImmediatePropagation();const value=app.el.querySelector('[data-local-topic]').value.trim();if(!value){app.el.querySelector('[data-local-topic]').focus();return;}app.previewDraftTopic=value;const project={id:'local-'+(app.previewProjects.length+1),topic:value,hasResults:false};app.previewProjects.push(project);localSwitch(app,project);},true);
    app.el.addEventListener('change',event=>{if(!event.target.matches('[data-local-project]'))return;event.stopImmediatePropagation();localSwitch(app,app.previewProjects.find(p=>p.id===event.target.value)||app.previewProjects[0]);},true);
    app.el.addEventListener('input',event=>{if(event.target.matches('[data-local-topic]'))app.previewDraftTopic=event.target.value;if(event.target.matches('[data-local-scope]')){app.previewScopeDraft=event.target.value;app.previewScopeSaved=false;}});
    app.el.addEventListener('toggle',event=>{if(event.target.matches('[data-local-operations]'))app.previewOps[Number(event.target.dataset.localOperations)]=event.target.open;if(event.target.matches('[data-local-results]'))app.previewResultsOpen[Number(event.target.dataset.localResults)]=event.target.open;if(event.target.matches('[data-local-process]'))app.previewProcessOpen[Number(event.target.dataset.localProcess)]=event.target.open;},true);
  });

