 3:[['研究问题与约束','Question & constraints','研究問題及限制'],['方案设计','Design','方案設計'],['可行性与资源','Feasibility & resources','可行性及資源'],['人工审阅','Human review','人工審閱'],['设计交付','Design delivery','設計交付']],
 4:[['实验输入','Experiment inputs','實驗輸入'],['执行与尝试','Execution & attempts','執行及嘗試'],['失败与恢复','Failures & recovery','失敗及恢復'],['结果检查','Result checks','結果檢查'],['执行交付','Execution delivery','執行交付']],
